  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --navy: oklch(14% 0.06 265);
      --navy-light: oklch(20% 0.07 265);
      --gold: oklch(75% 0.16 72);
      --gold-dark: oklch(65% 0.18 72);
      --blue-link: oklch(42% 0.22 265);
      --text-primary: oklch(18% 0.02 265);
      --text-secondary: oklch(45% 0.02 265);
      --text-muted: oklch(60% 0.01 265);
      --bg-body: oklch(99% 0.005 265);
      --bg-card: oklch(100% 0 0);
      --border: oklch(92% 0.01 265);
      --tag-ai: oklch(55% 0.22 265);
      --tag-scraping: oklch(48% 0.18 145);
      --tag-db: oklch(52% 0.20 300);
      --tag-es: oklch(55% 0.20 20);
      --tag-de: oklch(50% 0.18 185);
      --radius-card: 8px;
      --radius-btn: 6px;
      --shadow-card: 0 1px 3px oklch(0% 0 0 / 0.08), 0 4px 12px oklch(0% 0 0 / 0.05);
      --shadow-card-hover: 0 4px 16px oklch(0% 0 0 / 0.12), 0 8px 24px oklch(0% 0 0 / 0.08);
    }

    body { font-family: 'Inter', system-ui, -apple-system, sans-serif; background: var(--bg-body); color: var(--text-primary); line-height: 1.5; }

    /* ── Header ── */
    .site-header { background: var(--navy); color: #fff; position: sticky; top: 0; z-index: 100; box-shadow: 0 2px 8px oklch(0% 0 0 / 0.3); }
    .header-inner { max-width: 1200px; margin: 0 auto; padding: 0 24px; display: flex; align-items: center; gap: 16px; height: 60px; }
    .logo { display: flex; align-items: center; gap: 8px; text-decoration: none; color: #fff; font-weight: 700; font-size: 1rem; white-space: nowrap; }
    .logo-icon { width: 32px; height: 32px; background: var(--gold); border-radius: 6px; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 1rem; color: var(--navy); flex-shrink: 0; }
    .search-bar { flex: 1; max-width: 480px; position: relative; }
    .search-bar input { width: 100%; background: oklch(22% 0.05 265); border: 1px solid oklch(30% 0.05 265); color: #fff; border-radius: 6px; padding: 8px 12px 8px 36px; font-size: 0.85rem; font-family: inherit; outline: none; transition: border-color 0.2s; }
    .search-bar input::placeholder { color: oklch(60% 0.03 265); }
    .search-bar input:focus { border-color: var(--gold); }
    .search-bar svg { position: absolute; left: 10px; top: 50%; transform: translateY(-50%); opacity: 0.5; width: 16px; height: 16px; }
    .header-nav { display: flex; align-items: center; gap: 4px; margin-left: auto; }
    .header-nav a { color: oklch(80% 0.03 265); text-decoration: none; font-size: 0.9rem; font-weight: 500; padding: 6px 12px; border-radius: 6px; transition: color 0.2s, background 0.2s; white-space: nowrap; }
    .header-nav a:hover { color: #fff; background: oklch(22% 0.05 265); }
    .header-nav a.donate-link { color: var(--gold); }
    .header-nav a.donate-link:hover { background: oklch(22% 0.05 265); color: var(--gold-dark); }
    .hamburger { display: none; background: none; border: none; cursor: pointer; padding: 6px; color: #fff; }
    .mobile-nav { display: none; background: var(--navy-light); padding: 12px 24px; }
    .mobile-nav.open { display: block; }
    .mobile-nav a { display: block; color: oklch(80% 0.03 265); text-decoration: none; padding: 10px 0; border-bottom: 1px solid oklch(25% 0.04 265); font-size: 0.95rem; font-weight: 500; }
    .mobile-nav a:last-child { border-bottom: none; }

    /* ── Banner ── */
    .site-banner { background: oklch(25% 0.08 265); color: oklch(85% 0.05 265); text-align: center; padding: 10px 24px; font-size: 0.85rem; }
    .site-banner a { color: var(--gold); text-decoration: none; font-weight: 600; }
    .site-banner a:hover { text-decoration: underline; }

    /* ── Main Layout ── */
    .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
    .page-section { padding: 40px 0; }

    /* ── Featured Article ── */
    .featured-section { padding: 32px 0 0; }
    .featured-card { position: relative; border-radius: 12px; overflow: hidden; background: var(--navy); color: #fff; min-height: 380px; display: flex; align-items: flex-end; cursor: pointer; box-shadow: var(--shadow-card); transition: box-shadow 0.3s; }
    .featured-card:hover { box-shadow: var(--shadow-card-hover); }
    .featured-thumbnail { position: absolute; inset: 0; background: linear-gradient(135deg, oklch(20% 0.15 265) 0%, oklch(30% 0.10 200) 50%, oklch(25% 0.12 240) 100%); }
    .featured-thumbnail::after { content: ''; position: absolute; inset: 0; background: linear-gradient(to top, oklch(10% 0.05 265 / 0.95) 0%, oklch(10% 0.05 265 / 0.3) 60%, transparent 100%); }
    .featured-thumb-art { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; opacity: 0.15; font-size: 9rem; }
    .featured-content { position: relative; z-index: 1; padding: 32px; width: 100%; }
    .featured-tag { display: inline-block; background: var(--tag-ai); color: #fff; font-size: 0.72rem; font-weight: 600; padding: 3px 10px; border-radius: 20px; text-transform: uppercase; letter-spacing: 0.05em; margin-bottom: 12px; text-decoration: none; }
    .featured-tag:hover { opacity: 0.9; }
    .featured-title { font-size: clamp(1.4rem, 3vw, 2.2rem); font-weight: 800; line-height: 1.2; margin-bottom: 20px; max-width: 680px; }
    .featured-meta { display: flex; align-items: center; gap: 10px; }
    .avatar { width: 32px; height: 32px; border-radius: 50%; background: var(--gold); display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 0.8rem; color: var(--navy); flex-shrink: 0; }
    .meta-author { font-weight: 600; font-size: 0.9rem; }
    .meta-time { font-size: 0.82rem; color: oklch(70% 0.03 265); }
    .meta-dot { color: oklch(50% 0.02 265); }

    /* ── Section Headers ── */
    .section-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 24px; padding-bottom: 16px; border-bottom: 2px solid var(--border); }
    .section-title { font-size: 1.35rem; font-weight: 700; color: var(--text-primary); }
    .section-link { color: var(--blue-link); text-decoration: none; font-size: 0.875rem; font-weight: 600; }
    .section-link:hover { text-decoration: underline; }

    /* ── Article Grid ── */
    .article-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
    .article-card { background: var(--bg-card); border-radius: var(--radius-card); overflow: hidden; border: 1px solid var(--border); box-shadow: var(--shadow-card); transition: box-shadow 0.25s, transform 0.25s; cursor: pointer; }
    .article-card:hover { box-shadow: var(--shadow-card-hover); transform: translateY(-2px); }
    .card-thumbnail { aspect-ratio: 16/9; position: relative; overflow: hidden; }
    .card-thumb-bg { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; font-size: 3.5rem; }
    .card-thumb-bg.bg-ai { background: linear-gradient(135deg, oklch(20% 0.15 265), oklch(35% 0.18 240)); }
    .card-thumb-bg.bg-scraping { background: linear-gradient(135deg, oklch(25% 0.12 145), oklch(35% 0.15 165)); }
    .card-thumb-bg.bg-db { background: linear-gradient(135deg, oklch(22% 0.14 300), oklch(35% 0.16 280)); }
    .card-thumb-bg.bg-es { background: linear-gradient(135deg, oklch(25% 0.14 20), oklch(35% 0.16 45)); }
    .card-thumb-bg.bg-de { background: linear-gradient(135deg, oklch(22% 0.13 185), oklch(35% 0.15 160)); }
    .card-thumb-bg.bg-default { background: linear-gradient(135deg, oklch(22% 0.08 265), oklch(35% 0.10 240)); }
    .card-tag-overlay { position: absolute; top: 12px; left: 12px; }
    .tag-label { display: inline-block; color: #fff; font-size: 0.7rem; font-weight: 600; padding: 3px 9px; border-radius: 20px; text-transform: uppercase; letter-spacing: 0.04em; text-decoration: none; white-space: nowrap; }
    .tag-label:hover { opacity: 0.85; }
    .tag-ai { background: var(--tag-ai); }
    .tag-scraping { background: var(--tag-scraping); }
    .tag-db { background: var(--tag-db); }
    .tag-es { background: var(--tag-es); }
    .tag-de { background: var(--tag-de); }
    .tag-default { background: oklch(50% 0.10 265); }
    .card-body { padding: 16px; }
    .card-title { font-size: 0.95rem; font-weight: 700; line-height: 1.4; margin-bottom: 14px; color: var(--text-primary); display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
    .card-meta { display: flex; align-items: center; gap: 8px; }
    .card-avatar { width: 26px; height: 26px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 0.72rem; color: var(--navy); flex-shrink: 0; }
    .card-author { font-size: 0.8rem; font-weight: 600; color: var(--text-secondary); }
    .card-time { font-size: 0.78rem; color: var(--text-muted); margin-left: auto; }

    /* ── Load More ── */
    .load-more-wrap { text-align: center; padding: 36px 0 16px; }
    .btn-load-more { background: var(--bg-card); border: 2px solid var(--navy); color: var(--navy); font-family: inherit; font-size: 0.9rem; font-weight: 700; padding: 12px 32px; border-radius: var(--radius-btn); cursor: pointer; transition: background 0.2s, color 0.2s; }
    .btn-load-more:hover { background: var(--navy); color: #fff; }

    /* ── Footer ── */
    .site-footer { background: var(--navy); color: oklch(70% 0.03 265); padding: 48px 0 32px; margin-top: 64px; }
    .footer-grid { display: grid; grid-template-columns: 1.5fr 1fr 1fr; gap: 40px; margin-bottom: 40px; }
    .footer-mission { font-size: 0.875rem; line-height: 1.7; }
    .footer-logo { display: flex; align-items: center; gap: 8px; color: #fff; font-weight: 700; font-size: 1rem; margin-bottom: 14px; text-decoration: none; }
    .footer-col h4 { color: #fff; font-size: 0.85rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 14px; }
    .footer-tags { display: flex; flex-wrap: wrap; gap: 8px; }
    .footer-tag { color: oklch(65% 0.05 265); text-decoration: none; font-size: 0.82rem; padding: 4px 10px; border: 1px solid oklch(28% 0.04 265); border-radius: 20px; transition: color 0.2s, border-color 0.2s; }
    .footer-tag:hover { color: var(--gold); border-color: var(--gold); }
    .footer-links { display: flex; flex-wrap: wrap; gap: 10px 20px; }
    .footer-links a { color: oklch(60% 0.03 265); text-decoration: none; font-size: 0.82rem; transition: color 0.2s; }
    .footer-links a:hover { color: var(--gold); }
    .footer-bottom { border-top: 1px solid oklch(22% 0.04 265); padding-top: 24px; font-size: 0.8rem; text-align: center; }

    /* ── Responsive ── */
    @media (max-width: 900px) {
      .article-grid { grid-template-columns: repeat(2, 1fr); }
      .footer-grid { grid-template-columns: 1fr 1fr; }
    }
    @media (max-width: 640px) {
      .header-nav { display: none; }
      .hamburger { display: block; margin-left: auto; }
      .search-bar { max-width: none; flex: 1; }
      .article-grid { grid-template-columns: 1fr; }
      .footer-grid { grid-template-columns: 1fr; }
      .featured-card { min-height: 280px; }
      .featured-content { padding: 20px; }
    }
  </style>
</head>
